// App Router async server component - fetches request-time data
export default async function UserDashboard() {
  // Fetch user-specific preferences on each request (no cache)
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3000';
  const res = await fetch(`${baseUrl}/api/user/preferences`, {
    cache: 'no-store', // Ensure fresh data on every request
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>User preferences: {JSON.stringify(preferences)}</p>
    </div>
  );
}

